// School staff (admins and the owner) manage the student accounts of their
// school: create one or import a roster, assign a grade and a scope as the
// student's curriculum, reset a password, remove. Passwords are generated by
// the server and shown once, here, to hand to the student.
import { del, get, patch, post } from '../api.js';
import { confirmDialog, dialog, downloadText, errorMessage, fmtDate, fmtNum, form, h, problemText, tableCard, th, toast } from '../dom.js';
import { locale, t } from '../i18n.js';
import { can, invalidateOrg } from '../state.js';
import { pageHead, planLimitHint } from './shell.js';

// Grade names come with the list (the catalogue's names, e.g. "Preparatory 1").
let gradeNames = [];
const gradeLabel = (g) => {
  const n = gradeNames.find((x) => x.grade === g);
  return n ? (locale() === 'ar' ? n.nameAr : n.nameEn) : `${t('picker.grade')} ${g}`;
};

// Spreadsheet formula guard, as on the server (lib/csv.ts).
const cell = (v) => {
  let s = String(v ?? '');
  if (/^[=+\-@\t\r]/.test(s)) s = `'${s}`;
  return /[",;\n\r]/.test(s) ? `"${s.replace(/"/g, '""')}"` : s;
};
const csv = (rows) => `\uFEFF${rows.map((r) => r.map(cell).join(',')).join('\r\n')}\r\n`;

function signInLink(code) {
  return `${location.origin}/student-login?school=${encodeURIComponent(code)}`;
}

/** Shows freshly issued passwords once, with a download for printing or handing out. */
async function showCredentials(schoolCode, list) {
  const download = () => downloadText(`student-passwords-${schoolCode}.csv`,
    csv([['school_code', 'username', 'name', 'password', 'sign_in_link'], ...list.map((s) => [schoolCode, s.username, s.name, s.password, signInLink(schoolCode)])]), 'text/csv');
  const body = h('div', { class: 'stack' },
    h('p', { class: 'notice' }, t('students.passwordsOnce')),
    list.length <= 5
      ? h('dl', { class: 'kv' }, list.map((s) => [h('dt', {}, s.name, ' · ', h('span', { class: 'mono' }, s.username)), h('dd', { class: 'cred', dir: 'ltr' }, s.password)]))
      : h('p', {}, t('students.passwordsMany', { n: list.length })),
    h('p', { class: 'muted' }, t('students.schoolCodeIs'), ' ', h('span', { class: 'mono', dir: 'ltr' }, schoolCode)),
    h('div', {}, h('button', { type: 'button', class: 'btn', onclick: download }, t('students.downloadPasswords'))));
  await dialog({ title: t('students.passwordsTitle'), body, actions: [{ label: t('common.done'), value: true, kind: 'ghost' }] });
}

function studentForm({ scopes, initial = {}, withUsername, submitLabel, onSubmit }) {
  return form({
    fields: [
      withUsername ? { name: 'username', label: t('students.username'), required: true, autocomplete: 'off', maxlength: 40, hint: t('students.usernameHint'), value: initial.username } : null,
      { name: 'name', label: t('students.name'), required: true, autocomplete: 'off', maxlength: 120, value: initial.name },
      { name: 'grade', label: t('picker.grade'), type: 'select', value: String(initial.grade ?? 1), options: gradeNames.map((g) => ({ value: String(g.grade), label: gradeLabel(g.grade) })) },
      { name: 'scopeId', label: t('students.curriculum'), type: 'select', value: initial.scopeId ?? '', hint: t('students.curriculumHint'), options: [{ value: '', label: t('students.noScope') }, ...scopes.map((s) => ({ value: s.id, label: `${s.name} (${s.academicYear})` }))] },
    ].filter(Boolean),
    submitLabel,
    onSubmit: (v) => onSubmit({ ...v, grade: Number(v.grade), scopeId: v.scopeId || null }),
  });
}

async function importDialog(orgId, role) {
  let text = null;
  let preview = null;
  let applied = null;
  const status = h('div', { class: 'stack', role: 'status', 'aria-live': 'polite' });
  const file = h('input', { type: 'file', accept: '.csv,text/csv', id: 'roster-file' });
  const show = (...nodes) => status.replaceChildren(...nodes.flat().filter(Boolean));
  file.addEventListener('change', async () => {
    const f = file.files?.[0];
    preview = null;
    if (!f) return show();
    try {
      text = await f.text();
      preview = await post(`/api/orgs/${orgId}/students/import`, { csv: text, apply: false });
    } catch (err) {
      return show(h('div', { class: 'alert error' }, errorMessage(err)));
    }
    const room = preview.limit === null ? null : preview.limit - preview.used;
    show(
      h('p', {}, t('students.importFound', { n: preview.rows.length })),
      preview.errors.length ? [h('div', { class: 'alert error' }, t('students.importErrors', { n: preview.errors.length })),
        h('ul', {}, preview.errors.slice(0, 50).map((e) => h('li', {}, t('students.importLine', { line: e.line }), ' ', h('span', { dir: 'auto' }, problemText(e)))))] : null,
      room !== null && preview.rows.length > room ? h('div', { class: 'alert error' }, t('students.importOverLimit', { room, limit: preview.limit })) : null,
    );
  });
  const template = () => downloadText('students-template.csv', csv([['username', 'name', 'grade', 'scope'], ['ahmed.ali', 'Ahmed Ali', 7, ''], ['mona.hassan', 'منى حسن', 7, '']]), 'text/csv');
  const body = h('div', { class: 'stack' },
    h('p', {}, t('students.importHelp')),
    h('p', {}, h('button', { type: 'button', class: 'linkbtn', onclick: template }, t('students.template'))),
    h('div', { class: 'field' }, h('label', { for: 'roster-file' }, t('students.chooseFile')), file),
    status);
  const ok = await dialog({
    title: t('students.importTitle'), body,
    actions: [
      { label: t('common.cancel'), value: false, kind: 'ghost' },
      {
        label: t('students.importApply'), value: true, validate: async () => {
          if (!preview || preview.errors.length || !preview.rows.length) { file.focus(); return false; }
          try {
            applied = await post(`/api/orgs/${orgId}/students/import`, { csv: text, apply: true });
            return true;
          } catch (err) {
            show(h('div', { class: 'alert error', role: 'alert' }, errorMessage(err), ' ', planLimitHint(err, orgId, role)));
            return false;
          }
        },
      },
    ],
  });
  if (ok && applied) {
    toast(t('students.imported', { n: applied.created.length }));
    await showCredentials(applied.schoolCode, applied.created);
    return true;
  }
  return false;
}

export async function studentsView(ctx) {
  const { orgId } = ctx.params;
  const info = ctx.info;
  const role = info.role;
  if (!can(role, 'admin')) return h('div', {}, pageHead(t('students.title'), null), h('div', { class: 'alert' }, t('students.adminsOnly')));
  const [data, { scopes }] = await Promise.all([get(`/api/orgs/${orgId}/students`), get(`/api/orgs/${orgId}/scopes`)]);
  gradeNames = data.grades;
  const refresh = () => { invalidateOrg(orgId); ctx.render(); };
  const scopeName = (id) => scopes.find((s) => s.id === id)?.name;

  const head = pageHead(t('students.title'), t('students.sub'));
  if (!data.enabled && !data.students.length) {
    return h('div', {}, head, h('div', { class: 'card' }, h('h2', {}, t('students.offTitle')), h('p', {}, t('students.offText'))));
  }

  const addStudent = async () => {
    const f = studentForm({
      scopes, withUsername: true, submitLabel: t('students.add'), onSubmit: async (v) => {
        const r = await post(`/api/orgs/${orgId}/students`, v);
        f.el.closest('dialog')?.close();
        await showCredentials(data.schoolCode, [{ ...r.student, password: r.password }]);
        refresh();
      },
    });
    await dialog({ title: t('students.addTitle'), body: f.el, actions: [{ label: t('common.cancel'), value: null, kind: 'ghost' }] });
  };

  const edit = async (s) => {
    const f = studentForm({
      scopes, initial: s, withUsername: false, submitLabel: t('common.save'), onSubmit: async (v) => {
        await patch(`/api/orgs/${orgId}/students/${s.userId}`, v);
        f.el.closest('dialog')?.close();
        toast(t('common.saved'));
        refresh();
      },
    });
    await dialog({ title: t('students.editTitle', { name: s.name }), body: f.el, actions: [{ label: t('common.cancel'), value: null, kind: 'ghost' }] });
  };

  const act = async (fn) => { try { await fn(); } catch (err) { toast(errorMessage(err), 'error'); } };

  const copyBtn = h('button', {
    type: 'button', class: 'btn small ghost', onclick: () => {
      try { navigator.clipboard.writeText(signInLink(data.schoolCode)).then(() => toast(t('students.linkCopied')), () => toast(signInLink(data.schoolCode))); } catch { toast(signInLink(data.schoolCode)); }
    },
  }, t('students.copyLink'));

  const usage = data.limit === null ? null : Math.min(100, Math.round((data.used / Math.max(1, data.limit)) * 100));
  const meter = (used, max, pct) => {
    const bar = h('span', {});
    bar.style.width = `${pct}%`; // CSSOM style is allowed by the CSP (no inline style attributes)
    return h('div', { class: `meter ${pct >= 100 ? 'full' : ''}`, role: 'meter', 'aria-label': t('students.accounts'), 'aria-valuetext': `${fmtNum(used)} / ${fmtNum(max)}`, 'aria-valuemin': '0', 'aria-valuemax': String(max), 'aria-valuenow': String(used) }, bar);
  };
  const summary = h('div', { class: 'grid2' },
    h('div', { class: 'card' }, h('h2', {}, t('students.howTitle')),
      h('p', {}, t('students.howText')),
      h('p', {}, t('students.schoolCodeIs'), ' ', h('span', { class: 'code-big', dir: 'ltr' }, data.schoolCode)),
      h('p', { class: 'mono muted', dir: 'ltr' }, signInLink(data.schoolCode)),
      h('div', { class: 'row' }, copyBtn)),
    h('div', { class: 'card' }, h('h2', {}, t('students.accounts')),
      h('p', {}, t('students.used', { used: fmtNum(data.used), limit: fmtNum(data.limit) })),
      usage !== null ? meter(data.used, data.limit, usage) : null,
      data.enabled ? null : h('p', { class: 'notice' }, t('students.offExisting')),
      h('div', { class: 'row card-actions' },
        h('button', { type: 'button', class: 'btn', disabled: !data.enabled, onclick: () => act(addStudent) }, t('students.add')),
        h('button', { type: 'button', class: 'btn ghost', disabled: !data.enabled, onclick: () => act(async () => { if (await importDialog(orgId, role)) refresh(); }) }, t('students.import')))));

  const rows = data.students.map((s) => h('tr', {},
    h('td', {}, h('b', { dir: 'auto' }, s.name), h('div', { class: 'mono muted', dir: 'ltr' }, s.username)),
    h('td', {}, gradeLabel(s.grade)),
    h('td', { dir: 'auto' }, s.scopeName ?? scopeName(s.scopeId) ?? h('span', { class: 'muted' }, t('students.noScope'))),
    h('td', {}, s.locked ? h('span', { class: 'pill bad' }, t('students.locked')) : s.lastLoginAt ? fmtDate(s.lastLoginAt, true) : h('span', { class: 'muted' }, t('students.never'))),
    h('td', {}, h('div', { class: 'row' },
      h('button', { type: 'button', class: 'btn small ghost', 'aria-label': t('students.editFor', { name: s.name }), onclick: () => act(() => edit(s)) }, t('common.edit')),
      h('button', {
        type: 'button', class: 'btn small ghost', 'aria-label': t('students.resetFor', { name: s.name }), onclick: () => act(async () => {
          if (!(await confirmDialog(t('students.resetTitle'), t('students.resetText', { name: s.name }), { confirmLabel: t('students.reset') }))) return;
          const r = await post(`/api/orgs/${orgId}/students/${s.userId}/reset-password`);
          await showCredentials(data.schoolCode, [{ ...s, password: r.password }]);
          refresh();
        }),
      }, t('students.reset')),
      h('button', {
        type: 'button', class: 'btn small danger ghost', 'aria-label': t('students.removeFor', { name: s.name }), onclick: () => act(async () => {
          if (!(await confirmDialog(t('students.removeTitle'), t('students.removeText', { name: s.name }), { danger: true, confirmLabel: t('students.remove') }))) return;
          await del(`/api/orgs/${orgId}/students/${s.userId}`);
          toast(t('students.removed'));
          refresh();
        }),
      }, t('students.remove'))))));

  return h('div', {}, head, summary,
    data.students.length
      ? tableCard(t('students.title'), h('table', { class: 'data' },
        h('thead', {}, h('tr', {}, [t('students.student'), t('picker.grade'), t('students.curriculum'), t('students.lastSignIn'), ''].map(th))),
        h('tbody', {}, rows)))
      : h('p', { class: 'empty' }, t('students.none')),
    h('div', { class: 'card' }, h('h2', {}, t('students.privacyTitle')), h('p', {}, t('students.privacyText'))));
}
